// Package designconvert performs bounded, private syntax translation. A translation
// is not a runnable integration, security approval, or target-compatibility receipt.
package designconvert

import (
	"bytes"
	"crypto/sha256"
	"embed"
	"encoding/json"
	"fmt"
	"path"
	"runtime"
	"strings"
	"unicode/utf8"

	"cuelang.org/go/cue"
	"cuelang.org/go/cue/cuecontext"
)

// The rule digest covers the emitter, envelope and schema, including fixed config.
// Dependency pins below are separate: templ is REQUIRED to compile the output,
// not asserted to have compiled it during translation.
//
//go:embed html.go receipt.go schema.cue
var implementation embed.FS

const (
	RuleID            = "html-to-templ-v1"
	HTMLParserVersion = "golang.org/x/net@v0.54.0"
	RequiredTempl     = "github.com/a-h/templ@v0.3.1020"

	maxSourcePathBytes = 1024
	maxArchiveIDBytes  = 256
)

// Source identifies a single verified original; its body is supplied separately.
// A caller must verify archive integrity/access before invoking Translate.
type Source struct {
	ArchiveID string `json:"archive_id"`
	Path      string `json:"path"`
	SHA256    string `json:"sha256"`
	Size      int    `json:"size"`
}

type Transformer struct {
	ID            string `json:"id"`
	SHA256        string `json:"sha256"`
	GoVersion     string `json:"go_version"`
	HTMLParser    string `json:"html_parser"`
	RequiredTempl string `json:"required_templ"`
}

// Artifact is private derivative source, not independently distributable kit code.
// Mappings address original and generated bytes, not rendered DOM coordinates.
type Artifact struct {
	Filename string    `json:"filename"`
	SHA256   string    `json:"sha256"`
	Content  string    `json:"content"`
	Mappings []Mapping `json:"mappings"`
}

// Translation has deliberately no verified/pass compatibility state. A future
// target-evidence contract must not reinterpret this syntax-only envelope as one.
type Translation struct {
	SchemaVersion      int          `json:"schema_version"`
	Source             Source       `json:"source"`
	Target             string       `json:"target"`
	Transformer        Transformer  `json:"transformer"`
	Status             string       `json:"status"`
	Artifact           *Artifact    `json:"artifact,omitempty"`
	Diagnostics        []Diagnostic `json:"diagnostics"`
	OmittedDiagnostics int          `json:"omitted_diagnostics"`
	Verification       string       `json:"verification"`
}

// Translate performs no I/O, dependency installation, LLM calls or compilation.
// Unsupported inputs are a completed assessment with status=unsupported and no
// artifact. Corrupt identity/size or internal errors return an error instead.
func Translate(source Source, body []byte) (Translation, error) {
	if err := validateSource(source, body); err != nil {
		return Translation{}, err
	}
	result, err := translate(source, body)
	if err != nil {
		return Translation{}, err
	}
	if err := validateShape(result); err != nil {
		return Translation{}, err
	}
	return result, nil
}

func translate(source Source, body []byte) (Translation, error) {
	result := Translation{
		SchemaVersion: 1, Source: source, Target: "go-templ", Status: "unsupported",
		Transformer: Transformer{RuleID, ruleDigest(), runtime.Version(), HTMLParserVersion, RequiredTempl},
		Diagnostics: []Diagnostic{}, Verification: "not-verified",
	}
	if path.Ext(source.Path) != ".html" {
		result.Diagnostics = append(result.Diagnostics, Diagnostic{Code: "source-language", Offset: 0,
			Message: "This rule accepts official HTML fragments only; retain the original or select a reviewed source-native adapter."})
		return result, nil
	}
	converted, err := HTMLToTempl(body)
	if err != nil {
		return Translation{}, err
	}
	result.Diagnostics = append(result.Diagnostics, converted.Diagnostics...)
	result.OmittedDiagnostics = converted.OmittedDiagnostics
	if len(result.Diagnostics) != 0 || result.OmittedDiagnostics != 0 {
		if converted.Templ != "" || len(converted.Mappings) != 0 {
			return Translation{}, fmt.Errorf("designconvert: unsupported translation produced partial output")
		}
		return result, nil
	}
	if converted.Templ == "" {
		return Translation{}, fmt.Errorf("designconvert: translator produced no output or diagnostic")
	}
	result.Status = "translated"
	result.Artifact = &Artifact{Filename: "snippet.templ", SHA256: digest([]byte(converted.Templ)),
		Content: converted.Templ, Mappings: append([]Mapping{}, converted.Mappings...)}
	return result, nil
}

// VerifyReplay checks identity and exact deterministic replay under the current
// implementation/toolchain. It cannot approve visual, behavior or runtime fit.
// The caller must independently verify exact original archive membership and
// access: replay binds supplied bytes to their hash, not to an authenticated
// archive ID or member path supplied in the receipt.
func VerifyReplay(result Translation, body []byte) error {
	if err := validateShape(result); err != nil {
		return err
	}
	if err := validateSource(result.Source, body); err != nil {
		return err
	}
	expected, err := translate(result.Source, body)
	if err != nil {
		return err
	}
	got, err := json.Marshal(result)
	if err != nil {
		return err
	}
	want, err := json.Marshal(expected)
	if err != nil {
		return err
	}
	if !bytes.Equal(got, want) {
		return fmt.Errorf("designconvert: replay mismatch; source, rule, toolchain, diagnostics or artifact changed")
	}
	return nil
}

func validateSource(source Source, body []byte) error {
	if len(body) > MaxSourceBytes || source.Size != len(body) || !utf8.Valid(body) || bytes.IndexByte(body, 0) >= 0 {
		return fmt.Errorf("designconvert: source size or UTF-8 text is invalid")
	}
	if source.SHA256 != digest(body) {
		return fmt.Errorf("designconvert: source hash mismatch")
	}
	if len(source.Path) > maxSourcePathBytes || !utf8.ValidString(source.Path) ||
		source.Path == "." || source.Path == ".." || path.Clean(source.Path) != source.Path ||
		strings.HasPrefix(source.Path, "/") || strings.HasPrefix(source.Path, "../") ||
		strings.ContainsAny(source.Path, "\\\x00\r\n") {
		return fmt.Errorf("designconvert: source path must be an exact archive-relative member")
	}
	return nil
}

func validateShape(result Translation) error {
	if err := validateReceiptBounds(result); err != nil {
		return err
	}
	body, err := json.Marshal(result)
	if err != nil {
		return err
	}
	ctx := cuecontext.New()
	schema, err := implementation.ReadFile("schema.cue")
	if err != nil {
		return err
	}
	value := ctx.CompileBytes(body).Unify(ctx.CompileBytes(schema).LookupPath(cue.ParsePath("#Translation")))
	if err := value.Validate(cue.Concrete(true)); err != nil {
		return fmt.Errorf("designconvert: translation schema: %w", err)
	}
	return nil
}

// Bound every variable-size field before JSON escaping or CUE compilation. The
// schema owns semantic validity; these byte/count limits cap validation work,
// including for caller-supplied receipts that never passed through the emitter.
func validateReceiptBounds(result Translation) error {
	checkString := func(name, value string, limit int) error {
		if len(value) > limit {
			return fmt.Errorf("designconvert: receipt limit: %s exceeds %d bytes", name, limit)
		}
		if !utf8.ValidString(value) {
			return fmt.Errorf("designconvert: receipt encoding: %s must be UTF-8", name)
		}
		return nil
	}
	for _, field := range []struct {
		name, value string
		limit       int
	}{
		{"source.archive_id", result.Source.ArchiveID, maxArchiveIDBytes},
		{"source.path", result.Source.Path, maxSourcePathBytes},
		{"source.sha256", result.Source.SHA256, 64},
		{"target", result.Target, 128},
		{"transformer.id", result.Transformer.ID, 128},
		{"transformer.sha256", result.Transformer.SHA256, 64},
		{"transformer.go_version", result.Transformer.GoVersion, 256},
		{"transformer.html_parser", result.Transformer.HTMLParser, 256},
		{"transformer.required_templ", result.Transformer.RequiredTempl, 256},
		{"status", result.Status, 32},
		{"verification", result.Verification, 32},
	} {
		if err := checkString(field.name, field.value, field.limit); err != nil {
			return err
		}
	}
	if len(result.Diagnostics) > MaxDiagnostics {
		return fmt.Errorf("designconvert: receipt limit: diagnostics exceeds %d entries", MaxDiagnostics)
	}
	for _, diagnostic := range result.Diagnostics {
		if err := checkString("diagnostics.code", diagnostic.Code, 128); err != nil {
			return err
		}
		if err := checkString("diagnostics.message", diagnostic.Message, 1024); err != nil {
			return err
		}
	}
	if artifact := result.Artifact; artifact != nil {
		if len(artifact.Mappings) > maxTokens {
			return fmt.Errorf("designconvert: receipt limit: artifact.mappings exceeds %d entries", maxTokens)
		}
		if err := checkString("artifact.filename", artifact.Filename, 128); err != nil {
			return err
		}
		if err := checkString("artifact.sha256", artifact.SHA256, 64); err != nil {
			return err
		}
		if err := checkString("artifact.content", artifact.Content, maxOutputBytes); err != nil {
			return err
		}
	}
	return nil
}

func ruleDigest() string {
	h := sha256.New()
	for _, name := range []string{"html.go", "receipt.go", "schema.cue"} {
		body, _ := implementation.ReadFile(name) // go:embed guarantees these entries.
		fmt.Fprintf(h, "%s\x00%d\x00", name, len(body))
		h.Write(body)
	}
	return fmt.Sprintf("%x", h.Sum(nil))
}

func digest(body []byte) string { return fmt.Sprintf("%x", sha256.Sum256(body)) }
